/* Extended design review only: no auth service, model, Agent, MCP, database or code access. */
(() => {
  'use strict';
  const root=document.querySelector('#configuration-root');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pages={executions:['任务中心','查看用户提交的检查请求和处理进度。'],approvals:['审批中心','处理待审批的检查申请，查看历史决定。'],integrations:['Agent 与模型接入','登记执行连接，发现模型，再发布预设并绑定业务环境。'],runtime:['运行配置','管理 Agent 的执行节点、身份和隔离范围；业务环境在系统设置下绑定。'],context:['上下文与记忆','按来源和权限组装本轮材料，长期记忆需单独审核。'],users:['用户与权限','按可管理范围维护成员状态与授权；以下都是合成身份。'],records:['用户记录','按范围审阅合成问题、执行事实和资料；正文需要用途授权。']};
  const settings={auth:'agent_managed',acpVersion:'v1',mcpVersion:'2026-07-28',transport:'streamable-http',readCode:true,writeCode:false,terminal:false,network:'allowlist',isolation:'unverified',codeCommit:'demo-commit-a',deployment:'demo-commit-a',memory:'off',contextLimit:16000,outputReserve:4000};
  const J=window.ReviewJourney,users=J.users;
  const records=[{id:'demo-record-1',owner:'demo-tester',scope:'orders-test',title:'报表与明细差异（合成）',status:'待验证',text:'合成提问：报表金额和明细金额不一致。\n合成助手：请对齐时间与状态，再核对证据。本例尚待用户确认。',usage:'未上报实际费用',events:['用户条件已保存','唯一执行绑定：demo-binding-record-1','只读授权已确认（合成）','上下文清单已固定（合成）','合成结果已交付，待用户验证']},{id:'demo-record-2',owner:'demo-collaborator',scope:'orders-test',title:'接口超时核查（合成）',status:'核查中',text:'合成请求发生超时。必须核查原拥有者，不能改后端重复执行。',usage:'估算不可替代实际费用',events:['start 回执未知','原提交核查中','外部效果未知，保留拥有权']},{id:'demo-record-private',owner:'demo-tester',scope:'payments-test',title:'不可枚举记录',status:'处理中',text:'不可见',events:[]}];
  const audit=[],userDrafts=new Map();let memberQuery='',memberState='all';
  let page='integrations',actor='config',scenario='unknown',notice='',preflight=null,userId='demo-tester',userDraft=null,recordId='demo-record-1',query='',lease=null,leaseDrafts={},memoryState='candidate',leaseTimer=null,userOpen=false,recordOpen=false,initialized=false,openRequestedRecord=null;
  const roles={config:'配置管理员',access:'权限管理员',support:'支持审阅员',approver:'审批责任人',operator:'执行管理员'};
  const scopes=['orders-test','orders-stage'];
  const button=(id,text,extra='')=>`<button type="button" data-service="${id}" ${extra}>${text}</button>`;
  const select=(label,key,value,items)=>`<label class="admin-field">${label}<select data-service-field="${key}">${items.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
  const input=(label,key,value,type='text')=>`<label class="admin-field">${label}<input type="${type}" data-service-field="${key}" value="${esc(value)}"></label>`;
  const toggle=(label,key,value)=>`<label class="admin-toggle"><span>${label}</span><input type="checkbox" data-service-field="${key}" ${value?'checked':''}></label>`;
  function log(action,target){audit.unshift({action,target,actor:roles[actor],at:new Date().toISOString()});}
  function managementHeader(){return `<header class="management-topbar"><a class="management-logo" href="#chat"><span>✦</span>AI 测试协作台</a><nav class="management-switch" aria-label="工作空间"><a href="#chat">测试工作台</a><a href="#admin-executions" class="active">平台管理</a></nav><small>初始原型 · 无真实执行</small></header>`;}
  function navigation(active){return `<aside class="admin-sidebar"><a class="admin-brand" href="#admin-systems">◈ 平台管理</a><a class="admin-back" href="#chat">← 返回用户对话</a><div class="admin-nav-title">执行与审批</div><nav class="admin-operations-nav"><a href="#admin-executions" ${active==='executions'?'aria-current="page"':''}>任务中心</a><a href="#admin-approvals" ${active==='approvals'?'aria-current="page"':''}>审批中心</a></nav><div class="admin-nav-title service-nav-title">对话配置</div><nav class="admin-config-nav">${[['workflows','检查流程'],['resources','Skill 与 MCP 目录'],['systems','系统设置'],['permissions','权限配置']].map(([id,name])=>`<a href="#admin-${id}" ${(id===active||id==='systems'&&active==='environments'||id==='integrations'&&active==='models')?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="admin-nav-title service-nav-title">接入与治理</div><nav class="admin-service-nav">${Object.entries(pages).filter(([id])=>!['executions','approvals'].includes(id)).map(([id,[name]])=>`<a href="#admin-${id}" ${(id===active||id==='systems'&&active==='environments'||id==='integrations'&&active==='models')?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="admin-secondary"><details><summary>设计资料</summary><a href="#getting-started">首次开通演练</a><a href="#contract">执行契约与状态</a><a href="#approval">审批恢复演练</a></details><small>初始设计 · 离线演示<br>无真实接入与身份服务</small></div></aside>`;}
  function integrations(){return `<div class="service-three"><section class="service-card"><h2>模型访问</h2><p class="admin-muted">用户显示名来自模型预设，账号与密钥方式另行管理。</p>${select('账号管理方式','auth',settings.auth,[['agent_managed','Agent / 总控自行管理'],['secret_ref','受控宿主按引用注入']])}<dl><dt>凭据</dt><dd>${settings.auth==='agent_managed'?'只保存外部认证状态，不复制账号秘密':'仅保存秘密引用；原型无秘密值'}</dd><dt>数据出口</dt><dd>限定区域与服务目录；实际策略待验证</dd><dt>实际模型</dt><dd>未知，不能凭显示名称推断能力</dd></dl></section><section class="service-card"><h2>ACP 执行连接</h2>${select('协议支持分支','acpVersion',settings.acpVersion,[['v1','v1 · 当前设计基线'],['v2-draft','v2 · Draft，未准入']])}<dl><dt>生命周期</dt><dd>初始化 → 认证 → 新会话 → 事件 → 核查 / 停止</dd><dt>恢复与权限桥</dt><dd>逐能力发现；当前未验证</dd><dt>拥有者</dt><dd>固定 Binding，不透明切换后端</dd></dl></section><section class="service-card"><h2>MCP 工具连接</h2>${select('协议版本','mcpVersion',settings.mcpVersion,[['2026-07-28','2026-07-28'],['2025-11-25','2025-11-25 · 兼容分支']])}${select('传输','transport',settings.transport,[['streamable-http','Streamable HTTP'],['stdio','受控 stdio 子进程']])}<p class="admin-muted">两个 HTTP 版本的会话与流语义不同；不混用。工具清单、参数、风险、身份与预算分别检查。</p><span class="service-state">真实工具能力：未知</span></section></div><section class="service-card"><h2>接入条件预检</h2><p class="admin-muted">本地模拟策略检查，不探测端点，不安装或启动进程。</p>${select('演示故障','scenario',scenario,[['unknown','实际能力未知'],['schema','MCP schema 发生变化'],['bridge','审批桥接缺失'],['auth','认证已过期'],['scope','工具参数越界'],['timeout','工具调用结果未知'],['normal','设计条件齐全，仍待实测']])}${button('preflight','运行离线预检','class="admin-primary"')}${button('simulate-admission-change','模拟变更使当前计划失效')}<div id="service-preflight" role="status">${preflight?esc(preflight):'尚未运行预检。'}</div></section>`;}
  function runtime(){return `<div class="service-two"><section class="service-card"><h2>Agent 运行档案</h2><p class="admin-muted">业务环境：订单 / 测试。宿主模板：受控单 Agent。实际制品与隔离证据尚未配置。</p>${select('网络出口','network',settings.network,[['allowlist','仅登记的模型 / 资源服务'],['unrestricted','任意网络 · 禁止准入']])}${select('隔离证据','isolation',settings.isolation,[['unverified','未验证'],['design-only','仅策略草案，待实机证据']])}${toggle('允许受控代码读取','readCode',settings.readCode)}${toggle('允许写业务代码（本轮禁止）','writeCode',settings.writeCode)}${toggle('开放任意终端（本轮禁止）','terminal',settings.terminal)}<div class="admin-note">worktree 不是 OS 沙箱。原型不创建目录、不执行命令、不读取代码。</div></section><section class="service-card"><h2>代码与现场版本</h2>${input('代码快照（合成）','codeCommit',settings.codeCommit)}${input('现场部署版本（合成）','deployment',settings.deployment)}<div class="admin-resource"><span>允许范围</span><strong>登记仓库 / 固定 commit / 只读路径</strong><span>拒绝范围</span><strong>秘密文件、链接逃逸、跨租户目录</strong><span>证据定位</span><strong>repo / commit / path / 行号 / blobHash</strong><span>其他资源</span><strong>只读查询、脱敏日志、本会话附件</strong></div>${button('runtime-check','检查环境策略','class="admin-primary"')}<div id="runtime-result" role="status">${preflight&&page==='runtime'?esc(preflight):''}</div></section></div>`;}
  function context(){return `<div class="service-two"><section class="service-card"><h2>本轮上下文组装</h2>${input('总窗口预算（示例 token）','contextLimit',settings.contextLimit,'number')}${input('输出预留（示例 token）','outputReserve',settings.outputReserve,'number')}<ol class="service-list"><li>固定策略与操作计划</li><li>用户问题和明确条件</li><li>获准附件与当前版本代码证据</li><li>可追溯会话摘要</li><li>经审核且仍有效的记忆</li></ol>${button('context-check','生成合成材料清单','class="admin-primary"')}<div id="context-result" role="status">${preflight&&page==='context'?esc(preflight):''}</div><p class="admin-muted">实际模型窗口未知时仍阻断真实发送。过滤权限在检索之前，发出前再次核查。</p></section><section class="service-card"><h2>记忆策略</h2><p>记忆使用方式由上方已发布上下文策略及环境绑定决定，条目审核本身不授予访问权限。</p><p>合成条目：报表核对先对齐时间与状态。</p><dl><dt>来源</dt><dd>demo-record-1 / result-revision-1 · 合成</dd><dt>适用范围</dt><dd>订单 / 测试 · 原来源 ACL 仍有效才可用</dd><dt>条目状态</dt><dd id="memory-state">${esc(memoryState)}</dd></dl><div class="service-actions">${button('memory-review','审核候选')}${button('memory-activate','启用已审核条目')}${button('memory-revoke','撤销')}${button('memory-delete','请求删除')}${button('memory-source-revoke','模拟原来源撤权')}</div><p class="admin-muted">删除先进入 deletion_pending，待正文、索引、摘要及外部副本回执。不会把点击删除称为已经清除所有副本。</p></section></div>`;}
  const roleName=id=>({tester:'测试人员',observer:'协作成员',access:'权限管理员'}[id]||id);
  const modeName=id=>window.ResourceDesign.modes.find(([key])=>key===id)?.[1]||'继承策略';
  const scopeName=id=>{const d=window.ConfigurationPrototype.current(),env=d.environments.find(x=>x.id===id),sys=d.systems.find(x=>x.id===env?.system);return env?(sys?.name||env.system)+' / '+env.name:id;};
  function scopeSummary(user){const ids=user.scopes||window.ConfigurationPrototype.current().roles.find(r=>r.id===user.role)?.environments||[];return ids.length>2?ids.slice(0,2).map(scopeName).join('、')+' 等 '+ids.length+' 个':ids.map(scopeName).join('、')||'未配置';}
  const draftKey=id=>actor+':'+id;
  function freshDraft(user){const d=JSON.parse(JSON.stringify(user));if(d.scopes===null)d.scopes=[...(window.ConfigurationPrototype.current().roles.find(r=>r.id===user.role)?.environments||[])];return d;}
  function dirtyUser(user,draft=userDrafts.get(draftKey(user.id))){if(!draft)return false;const original=freshDraft(user);return draft.role!==original.role||JSON.stringify([...draft.scopes].sort())!==JSON.stringify([...original.scopes].sort())||(draft.executionMode||null)!==(original.executionMode||null)||JSON.stringify(draft.modelQuotas||{})!==JSON.stringify(original.modelQuotas||{})||!!draft.reason?.trim();}
  function rememberDraft(){if(!userDraft)return;userDrafts.set(draftKey(userId),JSON.parse(JSON.stringify(userDraft)));const status=root.querySelector('#member-draft-status');const dirty=dirtyUser(users.find(u=>u.id===userId));if(status)status.textContent=dirty?'未保存 · 关闭后保留本页草稿':'无未保存修改';const discard=root.querySelector('[data-service=reset-user-draft]');if(discard)discard.disabled=!dirty;const preview=root.querySelector('#effective-user-preview');if(preview){const open=!!preview.querySelector('details[open]');preview.innerHTML=effectiveUser(userDraft);preview.querySelector('details').open=open;}}
  function userPage(){const user=users.find(u=>u.id===userId);if(!userDraft||userDraft.id!==userId){const draft=userDrafts.get(draftKey(userId));if(draft&&draft.revision!==user.revision){userDrafts.delete(draftKey(userId));notice='原设置已变化，请基于当前设置重新编辑。';}userDraft=JSON.parse(JSON.stringify(userDrafts.get(draftKey(userId))||freshDraft(user)));}const visible=users.filter(u=>(memberState==='all'||u.status===memberState)&&(!memberQuery||[u.name,u.id].some(x=>x.toLowerCase().includes(memberQuery.toLowerCase()))));return `<section class="ops-panel"><div class="ops-panel-head"><h2>成员列表 <span class="ops-count">${visible.length}</span></h2><span class="ops-source-label">合成身份</span></div><div class="ops-filters">${input('搜索成员','memberQuery',memberQuery)}${button('search-members','搜索')}${select('账号状态','memberState',memberState,[['all','全部状态'],['active','正常'],['pending','待开通'],['unregistered','未加入'],['suspended','已暂停']])}${memberQuery||memberState!=='all'?button('reset-members','重置'):''}</div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>成员</th><th>角色</th><th>可用环境</th><th>执行方式</th><th>状态</th><th class="ops-action-col">操作</th></tr></thead><tbody>${visible.map(u=>`<tr><td class="ops-subject"><strong>${esc(u.name)}</strong>${dirtyUser(u)?'<small class="member-unsaved">未保存草稿</small>':''}</td><td class="ops-nowrap">${roleName(u.role)}</td><td>${esc(scopeSummary(u))}</td><td class="ops-nowrap">${modeName(u.executionMode)}</td><td><span class="ops-status ${u.status==='active'?'success':'muted'}">${({active:'正常',pending:'待开通',unregistered:'未加入',suspended:'已暂停'})[u.status]||'未知'}</span></td><td class="ops-action-col">${button('select-user','设置',`data-id="${u.id}" class="ops-link"`)}</td></tr>`).join('')||'<tr><td colspan="6"><div class="ops-empty"><strong>没有匹配的成员</strong><p>调整关键词或账号状态后重试。</p></div></td></tr>'}</tbody></table></div><footer class="ops-list-footer">共 ${visible.length} 位成员</footer></section>${userOpen?`<div class="daily-drawer-backdrop"></div><section class="daily-drawer" role="dialog" aria-modal="true" aria-labelledby="user-editor-title" tabindex="-1"><header><div><span class="ops-kicker">成员设置</span><small id="member-draft-status" class="member-draft-status">${dirtyUser(user)?'未保存 · 关闭后保留本页草稿':'无未保存修改'}</small><h2 id="user-editor-title">${esc(user.name)}</h2></div>${button('close-user','×','class="ops-close" aria-label="关闭成员设置"')}</header><div class="daily-drawer-body">${select('执行方式','userExecutionMode',userDraft.executionMode||'inherit',[['inherit','继承角色与环境策略'],...window.ResourceDesign.modes])}${select('成员角色','userRole',userDraft.role,[['tester','测试人员'],['observer','协作成员'],['access','权限管理员（不可授予）']])}<fieldset class="daily-scopes"><legend>可用环境</legend>${[...new Set([...window.ConfigurationPrototype.current().environments.map(e=>e.id),...userDraft.scopes])].map(id=>`<label class="admin-check"><input type="checkbox" data-user-scope="${id}" ${userDraft.scopes.includes(id)?'checked':''}>${scopeName(id)} ${scopes.includes(id)?'':(freshDraft(user).scopes.includes(id)?'· 已有授权，不能新增其他范围':'· 超出可授予范围')}</label>`).join('')}</fieldset><div id="effective-user-preview">${effectiveUser(userDraft)}</div>${window.ContextQuota.userEditor(window.ConfigurationPrototype.current(),userDraft)}${input('变更理由 / 工单','reason',userDraft.reason||'')}${user.joinRequest?`<p class="ops-hint">加入申请：${esc(user.joinRequest.reason)}</p>`:''}<p class="ops-hint">执行方式受角色权限与环境策略限制。</p><details class="ops-technical"><summary>授权信息</summary><p>${esc(user.id)} · 授权修订 ${user.revision}</p><p>可授予订单测试和预发环境；暂停后的在途动作需单独核查。</p></details><p class="daily-inline-feedback" role="status"></p></div><footer class="daily-drawer-footer">${button('reset-user-draft','放弃修改',dirtyUser(user)?'':'disabled')}${button('toggle-user',user.status==='active'?'暂停用户':user.status==='pending'?'开通成员':'恢复用户',user.status==='unregistered'?'disabled':'')}${button('save-user','保存设置','class="admin-primary"')}</footer></section>`:''}`;}
  function effectiveUser(u){const c=window.ConfigurationPrototype.current(),role=c.roles.find(r=>r.id===u.role),envs=c.environments.filter(e=>e.enabled&&role?.environments.includes(e.id)&&(u.scopes||role.environments).includes(e.id));return `<details class="admin-details"><summary>有效权限预览（当前草稿）</summary><p>${esc(({active:'正常',suspended:'已暂停',pending:'待开通',unregistered:'未加入'})[u.status]||u.status)} · 执行方式 ${esc(modeName(u.executionMode||role?.executionMode))}</p>${envs.map(e=>`<p>${esc(scopeName(e.id))}：${esc(c.models.filter(m=>m.enabled&&role.models.includes(m.id)&&e.allowedModelIds.includes(m.id)&&c.agentConnections.some(a=>a.id===m.connectionId&&a.enabled)).map(m=>m.agent+' / '+m.name).join('、')||'无可用模型')}</p>`).join('')||'<p>没有可用环境。</p>'}<small>仍需满足环境审批策略、额度及实际能力；暂停用户不能执行。</small></details>`;}
  function executionSummary(r){const p=r.preparation,g=p?.governanceSnapshot;return `<section class="record-binding-summary"><h3>本轮执行配置</h3>${p?`<dl class="ops-summary"><div><dt>执行连接 / Agent</dt><dd>${esc(g?.connection?.id||p.provider)} / ${esc(g?.connection?.agentId||'未知')}</dd></div><div><dt>模型</dt><dd>${esc(p.requestedModel)} · 实际模型未知</dd></div><div><dt>运行 / 上下文</dt><dd>${esc(g?.runtime?.name||'未记录')} / ${esc(g?.contextPolicy?.name||'未记录')}</dd></div><div><dt>MCP 工具</dt><dd>${esc((p.flowDecision?.toolBindings||[]).map(t=>t.connectionId+' / '+t.name).join('、')||'本轮未使用')}</dd></div><div><dt>额度来源</dt><dd>${esc(p.quotaSnapshot?.source||'未知')} · 真实用量未上报</dd></div></dl><p>来自本轮固定快照；配置更新不会改写此记录。</p>`:'<p>历史合成样例没有完整接入快照，不能用当前配置补作当时事实。</p>'}<p class="admin-muted">先核对状态和原执行引用；结果未知时交给执行管理员核查，不在记录页重跑。</p></section>`;}
  function recordPage(){const visible=['support','approver','operator'].includes(actor)?[...records,...J.records()].filter(r=>r.scope==='orders-test'&&(!query||r.title.includes(query)||r.owner.includes(query))):[];const r=visible.find(x=>x.id===recordId);const canRead=!!(r&&lease&&lease.id===r.id&&lease.expires>Date.now()&&lease.actor===actor);return `<section class="ops-panel"><div class="ops-panel-head"><h2>问题记录 <span class="ops-count">${visible.length}</span></h2><span class="ops-source-label">仅显示有权范围</span></div><div class="ops-filters">${input('搜索标题或用户','query',query)}${button('search-records','搜索')}${query?button('reset-records','重置'):''}</div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>检查事项</th><th>提交人</th><th>系统 / 环境</th><th>问题状态</th><th class="ops-action-col">操作</th></tr></thead><tbody>${visible.map(x=>`<tr><td class="ops-subject"><strong>${esc(x.title)}</strong></td><td>${esc(x.owner)}</td><td>${scopeName(x.scope)}</td><td><span class="ops-status neutral">${esc(x.status)}</span></td><td class="ops-action-col">${button('select-record','查看',`data-id="${x.id}" class="ops-link"`)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="ops-empty"><strong>暂无可访问的记录</strong><p>请检查搜索条件或当前角色范围。</p></div></td></tr>'}</tbody></table></div><footer class="ops-list-footer">共 ${visible.length} 条</footer></section>${recordOpen&&r?`<div class="daily-drawer-backdrop"></div><section class="daily-drawer" role="dialog" aria-modal="true" aria-labelledby="record-detail-title" tabindex="-1"><header><div><span class="ops-kicker">问题记录</span><h2 id="record-detail-title">${esc(r.title)}</h2></div>${button('close-record','×','class="ops-close" aria-label="关闭记录详情"')}</header><div class="daily-drawer-body"><dl class="ops-summary"><div><dt>用户</dt><dd>${esc(r.owner)}</dd></div><div><dt>系统 / 环境</dt><dd>${scopeName(r.scope)}</dd></div><div><dt>问题状态</dt><dd>${esc(r.status)}</dd></div><div><dt>费用</dt><dd>${esc(r.usage)}</dd></div></dl>${executionSummary(r)}<details class="ops-technical"><summary>处理记录与技术信息</summary><ol class="service-list">${r.events.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>${esc(r.preparation?JSON.stringify({context:r.preparation.id,backgroundSources:r.preparation.executionContext?.descriptions.map(d=>({kind:d.kind,id:d.id,revision:d.revision})),quota:r.preparation.quotaSnapshot,requestedModel:r.preparation.requestedModel,actualModel:r.preparation.actualModelId,code:r.preparation.codeSnapshot,mcp:r.preparation.mcpConnectionRef,memory:r.preparation.memoryRefs,binding:r.binding?.id,resultRevision:r.resultRevision}):'demo-runtime / demo-context-manifest / demo-code-commit / demo-mcp-schema')}</p></details>${actor==='approver'&&r.status==='待负责人审批'?button('approve-plan','审阅当前只读计划（合成）','class="admin-primary"'):''}<h3>对话内容</h3>${input('审阅理由 / 工单','leaseReason',leaseDrafts[actor+':'+recordId]||'')}<div class="service-actions">${button('lease','授权查看','class="admin-primary"')}${button('expire-lease','模拟租约过期')}</div><div id="record-content">${canRead?`<p class="service-sensitive">${esc(r.text)}</p><small>本次读取已记入合成审计；附件和下载另行授权。</small>`:'<p class="ops-hint">填写用途后，可申请本条记录的短期正文审阅。</p>'}</div><p class="daily-inline-feedback" role="status"></p></div></section>`:''}`;}
  function render(next,focus=false){
    const target=pages[next]?next:'integrations';const diagnosticOpen=target===page&&!!root.querySelector('.governance-diagnostics[open]');if(!initialized){actor=({approvals:'approver',executions:'operator',users:'access',records:'support'})[target]||'config';initialized=true;}if(target!==page){preflight=null;userOpen=false;recordOpen=false;}page=target;if(openRequestedRecord&&page==='records'){recordId=openRequestedRecord;recordOpen=true;openRequestedRecord=null;}root.dataset.mode='service';root.dataset.servicePage=page;
    root.innerHTML=managementHeader()+navigation(page)+`<main class="admin-main ${['executions','approvals','users','records'].includes(page)?'daily-main':''}"><header class="admin-heading"><div><div class="admin-eyebrow">平台管理 / ${['executions','approvals'].includes(page)?'日常处理':'设置与记录'}</div><h1 tabindex="-1">${pages[page][0]}</h1><p>${pages[page][1]}</p></div><div class="daily-role">${select('演示身份','actor',actor,Object.entries(roles))}<small>离线原型</small></div></header><div id="service-feedback" role="status" aria-live="polite">${esc(notice)}</div>${['integrations','runtime','context'].includes(page)?`<p class="admin-note">${page==='context'?'上下文策略发布后供绑定的环境使用；记忆条目仍需单独审核。':'配置可应用到离线演示；模拟发现不代表认证成功或真实隔离已验证。'}</p>`:''}${['integrations','runtime','context'].includes(page)?window.GovernanceDesign.view(page)+`<details class="governance-diagnostics admin-details" ${diagnosticOpen?'open':''}><summary>${page==='context'?'记忆详情与操作 / 高级演练':'高级诊断（离线故障演练）'}</summary>${({integrations,runtime,context})[page]()}</details>`:({executions:()=>window.ExecutionManagement.view('executions',actor),approvals:()=>window.ExecutionManagement.view('approvals',actor),users:userPage,records:recordPage})[page]()}<details class="admin-audit"><summary>本次合成治理审计（${audit.length}）</summary>${audit.map(a=>`<p>${esc(a.actor)} · ${esc(a.action)} · ${esc(a.target)} · ${a.at}</p>`).join('')||'<p>暂无操作。</p>'}</details></main><dialog id="service-dialog" aria-labelledby="service-dialog-title"></dialog>`;
    if(focus)root.querySelector('h1').focus();
    const dialog=root.querySelector('#service-dialog');dialog.addEventListener('cancel',()=>setTimeout(()=>root.querySelector(dialog.dataset.origin?'[data-ops='+dialog.dataset.origin+']':'[data-service=save-user],[data-service=approve-plan]')?.focus(),0));
    const drawer=root.querySelector('.ops-drawer,.daily-drawer');root.querySelector('.admin-sidebar').inert=!!drawer;root.querySelector('.management-topbar').inert=!!drawer;for(const child of root.querySelector('main').children)child.inert=!!drawer&&!child.matches('.ops-drawer,.daily-drawer,.ops-drawer-backdrop,.daily-drawer-backdrop');
  }
  const feedback=text=>{notice=text;root.querySelector('#service-feedback').textContent=text;const inline=root.querySelector('.daily-inline-feedback');if(inline)inline.textContent=text;};
  root.addEventListener('input',e=>{
    if(root.dataset.mode!=='service')return;if(e.type==='input'&&e.target.dataset.userQuota){const v=e.target.value;userDraft.modelQuotas[e.target.dataset.quotaKey][e.target.dataset.userQuota]=v===''?null:Number(v);rememberDraft();return;}if(e.type==='change'&&e.target.dataset.quotaMode){userDraft.modelQuotas??={};const k=e.target.dataset.quotaMode;if(e.target.value==='inherit')delete userDraft.modelQuotas[k];else userDraft.modelQuotas[k]={...window.ContextQuota.defaults,...window.ConfigurationPrototype.current().quotaDefaults[0]};rememberDraft();render(page);root.querySelector('.member-quotas').open=true;root.querySelector('[data-quota-mode="'+k+'"]')?.focus();return;}const key=e.target.dataset.serviceField;
    if(!key||e.target.tagName==='SELECT'||e.target.type==='checkbox')return;
    if(key==='reason'){userDraft.reason=e.target.value;rememberDraft();return;}
    if(key==='memberQuery'){memberQuery=e.target.value;return;}
    if(key==='query'){query=e.target.value;return;}
    if(key==='leaseReason'){leaseDrafts[actor+':'+recordId]=e.target.value;return;}
    settings[key]=e.target.type==='number'?Number(e.target.value):e.target.value;preflight=null;
  });
  root.addEventListener('change',e=>{
    if(root.dataset.mode!=='service')return;if(e.type==='input'&&e.target.dataset.userQuota){const v=e.target.value;userDraft.modelQuotas[e.target.dataset.quotaKey][e.target.dataset.userQuota]=v===''?null:Number(v);rememberDraft();return;}if(e.type==='change'&&e.target.dataset.quotaMode){userDraft.modelQuotas??={};const k=e.target.dataset.quotaMode;if(e.target.value==='inherit')delete userDraft.modelQuotas[k];else userDraft.modelQuotas[k]={...window.ContextQuota.defaults,...window.ConfigurationPrototype.current().quotaDefaults[0]};rememberDraft();render(page);root.querySelector('.member-quotas').open=true;root.querySelector('[data-quota-mode="'+k+'"]')?.focus();return;}const key=e.target.dataset.serviceField;
    if(e.target.dataset.userScope){const id=e.target.dataset.userScope;userDraft.scopes=e.target.checked?[...new Set([...userDraft.scopes,id])]:userDraft.scopes.filter(x=>x!==id);rememberDraft();return;}
    if(!key||e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')return;
    if(key==='actor'){actor=e.target.value;userDraft=null;lease=null;notice='';}
    else if(key==='memberState')memberState=e.target.value;
    else if(key==='scenario')scenario=e.target.value;
    else if(key==='userRole')userDraft.role=e.target.value;
    else if(key==='userExecutionMode')userDraft.executionMode=e.target.value==='inherit'?null:e.target.value;
    else {settings[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='memory')J.updateMemory({mode:settings.memory});}
    if(['userRole','userExecutionMode'].includes(key))rememberDraft();preflight=null;render(page);root.querySelector('[data-service-field="'+key+'"]')?.focus({preventScroll:true});
  });
  root.addEventListener('keydown',e=>{if(root.dataset.mode==='service'&&['query','memberQuery'].includes(e.target.dataset.serviceField)&&e.key==='Enter'){e.preventDefault();if(e.target.dataset.serviceField==='memberQuery')memberQuery=memberQuery.trim();else{query=query.trim();recordId='';recordOpen=false;}const key=e.target.dataset.serviceField;render(page);root.querySelector('[data-service-field='+key+']')?.focus();}});
  root.addEventListener('keydown',e=>{const drawer=root.querySelector('.daily-drawer');if(!drawer||root.querySelector('#service-dialog[open]'))return;if(e.key==='Escape'){e.preventDefault();root.querySelector('[data-service=close-user],[data-service=close-record]')?.click();}if(e.key==='Tab'){const list=[...drawer.querySelectorAll('button:not([disabled]),input,select,summary')].filter(x=>x.getClientRects().length);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus();}}});
  root.addEventListener('click',e=>{
    if(e.target.classList.contains('daily-drawer-backdrop')){root.querySelector('[data-service=close-user],[data-service=close-record]')?.click();return;}
    if(root.dataset.mode!=='service')return;const b=e.target.closest('[data-service]');if(!b)return;const action=b.dataset.service;
    if(['preflight','runtime-check','context-check','memory-review','memory-activate','memory-revoke','memory-delete','memory-source-revoke'].includes(action)&&actor!=='config'){feedback('当前演示角色没有配置 / 记忆管理权限。');return;}
    if(action==='simulate-admission-change'){if(actor!=='config'){feedback('当前角色不能模拟接入变更。');return;}J.integrationChanged(scenario);log('接入观察变更，计划需复查',scenario);notice='已更新合成接入修订。旧计划失效，已有执行绑定保留。';render(page);return;}
    if(action==='preflight'){const failures={unknown:'阻断：实际模型与 Agent / MCP 能力未知。',schema:'阻断：工具 schema 摘要变化，需重新审核参数与计划。',bridge:'阻断：审批桥接未验证，不允许自动响应权限。',auth:'阻断：认证已过期，需责任人恢复认证。',scope:'阻断：工具参数超出允许环境或资源范围，不允许执行。',timeout:'结果未知：保留原 invocation 引用并核查，禁止新键重做。',normal:'设计条件齐全；真实认证、隔离、能力和执行仍未验证，不能真实启动。'};preflight=settings.acpVersion==='v2-draft'?'阻断：v2 为 Draft，适配器未准入。':failures[scenario];log('离线接入预检',scenario);render(page);return;}
    if(action==='runtime-check'){const blockers=[];if(settings.writeCode)blockers.push('禁止写业务代码');if(settings.terminal)blockers.push('禁止任意终端');if(settings.network!=='allowlist')blockers.push('禁止任意网络');if(!settings.codeCommit.trim()||!settings.deployment.trim())blockers.push('缺少固定版本');else if(settings.codeCommit!==settings.deployment)blockers.push('代码与部署版本不一致，只能给有限结论');blockers.push('真实隔离尚未验证');preflight='阻断：'+blockers.join('；');render(page);return;}
    if(action==='context-check'){const total=settings.contextLimit,reserve=settings.outputReserve;preflight=!Number.isInteger(total)||!Number.isInteger(reserve)||total<1||reserve<1||reserve>=total?'阻断：上下文预算必须为正整数，且需保留足够输入空间。':`合成清单：当前问题、获准代码片段和证据、来源可追溯摘要；长期记忆${settings.memory==='off'?'关闭':'仅限审核通过且原 ACL 仍有效的条目'}。输入预算 ${total-reserve}，输出预留 ${reserve}；真实模型窗口未知，实际发送仍阻断。`;render(page);return;}
    if(action==='memory-source-revoke'){J.updateMemory({sourceAccess:false});log(action,'demo-memory-1');notice='原来源已撤权，相关上下文、结果与正文租约失效。';render(page);return;}
    if(action==='memory-review'){if(memoryState!=='candidate'){feedback('只有候选条目可以审核。');return;}memoryState='reviewed';}
    if(action==='memory-activate'){if(memoryState!=='reviewed'){feedback('须先审核，再启用；候选和已撤销条目不可直接进入上下文。');return;}memoryState='active';}
    if(action==='memory-revoke')memoryState='revoked';
    if(action==='memory-delete')memoryState='deletion_pending';
    if(action.startsWith('memory-')){J.updateMemory({state:memoryState});log(action,'demo-memory-1');render(page);return;}
    if(action==='search-members'||action==='reset-members'){memberQuery=action==='reset-members'?'':memberQuery.trim();if(action==='reset-members')memberState='all';render(page);root.querySelector('[data-service-field=memberQuery]')?.focus();return;}
    if(action==='search-records'||action==='reset-records'){query=action==='reset-records'?'':query.trim();recordOpen=false;render(page);root.querySelector('[data-service-field=query]')?.focus();return;}
    if(action==='reset-user-draft'){userDrafts.delete(draftKey(userId));userDraft=null;render(page);return;}
    if(action==='select-user'){userId=b.dataset.id;userDraft=null;userOpen=true;render(page);root.querySelector('.daily-drawer .ops-close')?.focus();return;}
    if(action==='close-user'||action==='close-record'){const target=action==='close-user'?'select-user':'select-record',id=action==='close-user'?userId:recordId;if(action==='close-user'&&dirtyUser(users.find(u=>u.id===userId)))notice='未保存的成员设置已保留为本页草稿。';userOpen=false;recordOpen=false;userDraft=null;lease=null;render(page);root.querySelector(`[data-service=${target}][data-id="${id}"]`)?.focus();return;}
    if(action==='save-user'||action==='toggle-user'){
      const u=users.find(x=>x.id===userId);if(actor!=='access'){feedback('当前演示角色没有 users.manage 权限。');return;}
      if(u.id==='demo-admin'){feedback('禁止修改自身身份或自行提权。');return;}
      if(u.status==='unregistered'){feedback('用户尚未提交加入申请，不能代为注册或开通。');return;}
      if(action==='toggle-user'&&u.status==='pending'&&!userDraft.scopes.length){feedback('请先选择至少一个可用环境再开通成员。');return;}
      if(Object.values(userDraft.modelQuotas||{}).some(q=>!window.ContextQuota.valid(q))){feedback('额度须为范围内的非负整数，0 表示禁止新调用。');return;}
      if(!userDraft.reason||userDraft.reason.trim().length<5){feedback('请填写至少 5 字的变更理由 / 工单。');return;}
      if(userDraft.scopes.some(x=>!scopes.includes(x)&&!(u.scopes||window.ConfigurationPrototype.current().roles.find(r=>r.id===u.role)?.environments||[]).includes(x))||!['tester','observer'].includes(userDraft.role)){feedback('超出可授予的角色或环境范围。');return;}
      const dialog=root.querySelector('#service-dialog');dialog.innerHTML=`<h2 id="service-dialog-title">确认合成用户变更</h2><p>${esc(u.name)} · ${action==='toggle-user'?(u.status==='active'?'暂停后续使用':u.status==='pending'?'开通成员 / '+userDraft.role+' / '+userDraft.scopes.join(', '):'恢复使用，不恢复旧批准'):esc(userDraft.role+' / '+userDraft.scopes.join(', '))}</p><p>执行方式：${esc(window.ResourceDesign.modes.find(([id])=>id===userDraft.executionMode)?.[1]||'继承角色与环境策略')}；有效方式仍取权限与环境交集。</p><p>额度：${esc(Object.entries(userDraft.modelQuotas||{}).map(([k,v])=>k+'：每日 '+v.dailyCalls+' 次 / '+v.dailyTokens+' Token，单轮 '+v.maxCalls+' 次，并发 '+v.concurrency).join('；')||'全部继承全局默认')}。未单独设置的组合继续继承。</p><p>理由：${esc(userDraft.reason)}</p>${button('cancel','继续编辑')}${button(action==='toggle-user'?'confirm-toggle':'confirm-save','确认变更','class="admin-primary"')}`;dialog.showModal();return;
    }
    if(action==='cancel'){root.querySelector('#service-dialog').close();return;}
    if(action==='confirm-save'||action==='confirm-toggle'){const u=users.find(x=>x.id===userId);if(actor!=='access'||u.id==='demo-admin'||userDraft.revision!==u.revision||Object.values(userDraft.modelQuotas||{}).some(q=>!window.ContextQuota.valid(q))){feedback('变更权限或修订冲突，需重新检查。');return;}if(action==='confirm-save'){u.role=userDraft.role;u.scopes=[...userDraft.scopes];u.executionMode=userDraft.executionMode||null;u.modelQuotas=JSON.parse(JSON.stringify(userDraft.modelQuotas||{}));}else {if(u.status==='pending'){u.role=userDraft.role;u.scopes=[...userDraft.scopes];u.executionMode=userDraft.executionMode||null;u.modelQuotas=JSON.parse(JSON.stringify(userDraft.modelQuotas||{}));}u.status=u.status==='active'?'suspended':'active';}u.revision++;userDrafts.delete(draftKey(userId));J.userChanged();log(action,u.id);lease=null;userDraft=null;notice='已更新合成用户样例；真实身份服务和在途撤权仍未实现。';render(page);return;}
    if(action==='approve-plan'){const r=J.records().find(x=>x.id===recordId);if(actor!=='approver'||r?.scope!=='orders-test'||r.status!=='待负责人审批'){feedback('无权处理此计划或计划已失效。');return;}const dialog=root.querySelector('#service-dialog');dialog.innerHTML=`<h2 id="service-dialog-title">确认这份只读计划？</h2><p>${esc(r.title)} / ${esc(r.scope)}<br>模型：${esc(r.preparation.requestedModel)}<br>上下文：${esc(r.preparation.id)}<br>固定输入修订：${r.preparation.inputRevision}；不包含写入。合成演示，不调用真实资源。</p>${button('cancel','取消')}${button('confirm-plan','批准这份计划','class="admin-primary"')}`;dialog.dataset.contextRef=r.preparation.id;dialog.showModal();return;}
    if(action==='confirm-plan'){const dialog=root.querySelector('#service-dialog');if(actor!=='approver'){feedback('当前角色不能审批此计划。');return;}const result=J.approve(recordId,dialog.dataset.contextRef);log('负责人计划审批',recordId);notice=result.ok?'负责人已确认本计划，等待合成结果；用户验收仍独立。':result.reason;render(page);return;}
    if(action==='select-record'){recordId=b.dataset.id;lease=null;recordOpen=true;render(page);root.querySelector('.daily-drawer .ops-close')?.focus();return;}
    if(action==='lease'){const r=[...records,...J.records()].find(x=>x.id===recordId),reason=root.querySelector('[data-service-field=leaseReason]')?.value||'';if(actor!=='support'||r?.scope!=='orders-test'){feedback('当前角色或记录范围不允许正文审阅。');return;}if(reason.trim().length<5){feedback('需填写至少 5 字的用途理由 / 工单。');return;}lease={id:r.id,expires:Date.now()+5*60*1000,actor};clearTimeout(leaseTimer);leaseTimer=setTimeout(()=>{lease=null;notice='内容租约已自动到期，正文已隐藏。';if(root.dataset.mode==='service'&&['records','executions','approvals'].includes(page))render(page);},5*60*1000);log('正文租约及读取：'+reason,r.id);notice='已取得本条合成记录的短期用途租约；不包含附件下载。';render(page);return;}
    if(action==='expire-lease'){lease=null;clearTimeout(leaseTimer);notice='内容租约已过期，正文不再显示。';render(page);}
  });
  J.subscribeRecords(()=>{if(root.dataset.mode==='service'&&['records','executions','approvals'].includes(page))render(page);});
  window.ConfigurationPrototype.subscribe(()=>{if(lease){lease=null;clearTimeout(leaseTimer);notice='授权配置变化，正文租约已失效。';if(root.dataset.mode==='service'&&['records','executions','approvals'].includes(page))render(page);}});
  J.subscribe(()=>{if(lease){lease=null;clearTimeout(leaseTimer);notice='授权或材料已变化，正文租约已失效。';}if(root.dataset.mode==='service'&&['records','executions','approvals'].includes(page))render(page);});
  window.ServiceDesignPrototype={managementHeader,actor:()=>actor,openRecord(id){recordId=id;query='';openRequestedRecord=id;location.hash='admin-records';},pages,navigation,render,inspect:()=>JSON.parse(JSON.stringify({settings,users,audit,memoryState,lease})),has:id=>Object.hasOwn(pages,id),hide(){lease=null;userOpen=false;recordOpen=false;window.ExecutionManagement.hide();clearTimeout(leaseTimer);}};
})();
